package offline;

import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;

/**
 * Offline receive audit for one trace.
 *
 * <p>The audit walks datagram events, frames each reached header, reconstructs packet numbers,
 * applies routing, authentication and key-epoch precedence, evaluates frame effects inside a
 * per-packet transaction, and finally normalises accepted packets into canonical envelopes.
 * Committed state is reported exactly as the contract describes.
 */
public final class ReceiveAudit {

    private static final int LEVEL_I = 0;
    private static final int LEVEL_H = 1;
    private static final int LEVEL_A = 2;
    private static final String[] LEVEL_NAMES = {"I", "H", "A"};

    private static final String BAD_HEADER = "BAD_HEADER";
    private static final String CLOSED = "CLOSED";
    private static final String DROP_CID = "DROP_CID";
    private static final String NO_KEY = "NO_KEY";
    private static final String PN_RANGE = "PN_RANGE";
    private static final String AUTH = "AUTH";
    private static final String DUPLICATE = "DUPLICATE";
    private static final String OK = "OK";
    private static final String PEER_CLOSE = "PEER_CLOSE";
    private static final String KEY_UPDATE_ERROR = "KEY_UPDATE_ERROR";
    private static final String FRAME_ENCODING_ERROR = "FRAME_ENCODING_ERROR";
    private static final String PROTOCOL_VIOLATION = "PROTOCOL_VIOLATION";
    private static final String STREAM_STATE_ERROR = "STREAM_STATE_ERROR";
    private static final String STREAM_LIMIT_ERROR = "STREAM_LIMIT_ERROR";
    private static final String FINAL_SIZE_ERROR = "FINAL_SIZE_ERROR";
    private static final String FLOW_CONTROL_ERROR = "FLOW_CONTROL_ERROR";
    private static final String CONNECTION_ID_LIMIT_ERROR = "CONNECTION_ID_LIMIT_ERROR";

    private static final long ERROR_FRAME_ENCODING = 0x07;
    private static final long ERROR_KEY_UPDATE = 0x0e;

    /** Aborts the current packet with the status name that the audit must report. */
    private static final class Fail extends RuntimeException {
        private final String status;

        Fail(String status) {
            this.status = status;
        }
    }

    /** Per-level receive bookkeeping: seen packet numbers, ACK union, ECN maxima and crypto bytes. */
    private static final class LevelState {
        long largest = -1;
        boolean seeded;
        final java.util.HashSet<Long> seen = new java.util.HashSet<>();
        final AuditIo.Ranges acknowledged = new AuditIo.Ranges();
        final long[] ecn = new long[3];
        final AuditIo.Ledger crypto = new AuditIo.Ledger();
    }

    /** Explicitly referenced stream state. */
    private static final class Stream {
        final long id;
        long high;
        Long finalSize;
        Long reset;
        Long stop;
        long sendMax;
        final AuditIo.Ledger bytes = new AuditIo.Ledger();

        Stream(long id) {
            this.id = id;
        }
    }

    /** Header fields shared by every successfully framed envelope. */
    private static final class Envelope {
        int level;
        byte[] destination;
        byte[] source;
        byte[] token;
        int phase;
        int numberWidth;
        long numberRaw;
        int payloadStart;
        int envelopeEnd;
    }

    /** One decoded frame plus everything needed to normalise it again. */
    private static final class Frame {
        int type;
        int start;
        int end;

        long largest;
        long delay;
        long first;
        long[][] pairs = new long[0][];
        long[][] ranges = new long[0][];
        long[] ecn;

        long id;
        long offset;
        long length;
        long maximum;
        long error;
        long sequence;
        long retirePriorTo;
        long limit;
        byte[] data = new byte[0];
        byte[] token = new byte[0];
        boolean fin;
        boolean hasOffset;
        boolean hasLength;

        int streamType() {
            return type;
        }

        void write(AuditIo.ByteOut out) {
            out.u8(type);
            switch (type) {
                case 0x00:
                case 0x01:
                case 0x1e:
                case 0x07:
                    break;
                case 0x02:
                case 0x03:
                    out.v(largest);
                    out.v(delay);
                    out.v(pairs.length);
                    out.v(first);
                    for (long[] pair : pairs) {
                        out.v(pair[0]);
                        out.v(pair[1]);
                    }
                    if (type == 0x03) {
                        out.v(ecn[0]);
                        out.v(ecn[1]);
                        out.v(ecn[2]);
                    }
                    break;
                case 0x04:
                    out.v(id);
                    out.v(error);
                    out.v(limit);
                    break;
                case 0x05:
                    out.v(id);
                    out.v(error);
                    break;
                case 0x06:
                    out.v(offset);
                    out.v(length);
                    out.bytes(data);
                    break;
                case 0x08:
                case 0x09:
                case 0x0a:
                case 0x0b:
                case 0x0c:
                case 0x0d:
                case 0x0e:
                case 0x0f:
                    out.v(id);
                    if (hasOffset) {
                        out.v(offset);
                    }
                    if (hasLength) {
                        out.v(length);
                    }
                    out.bytes(data);
                    break;
                case 0x10:
                case 0x12:
                case 0x13:
                case 0x14:
                case 0x16:
                case 0x17:
                    out.v(maximum);
                    break;
                case 0x11:
                case 0x15:
                    out.v(id);
                    out.v(maximum);
                    break;
                case 0x18:
                    out.v(sequence);
                    out.v(retirePriorTo);
                    out.u8(data.length);
                    out.bytes(data);
                    out.bytes(token);
                    break;
                case 0x19:
                    out.v(sequence);
                    break;
                case 0x1a:
                case 0x1b:
                    out.bytes(data);
                    break;
                case 0x1c:
                    out.v(error);
                    out.v(limit);
                    out.v(data.length);
                    out.bytes(data);
                    break;
                case 0x1d:
                    out.v(error);
                    out.v(data.length);
                    out.bytes(data);
                    break;
                case 0x30:
                    out.bytes(data);
                    break;
                case 0x31:
                    out.v(length);
                    out.bytes(data);
                    break;
                default:
                    throw new IllegalStateException("unserializable frame type " + type);
            }
        }
    }

    // ---------------------------------------------------------------- configuration

    private long limitConnection;
    private long limitStream;
    private long limitBidi;
    private long limitUni;
    private long cidLimit;
    private long localBidi;
    private long localUni;
    private byte[][] localCids;
    private int cidWidth;
    private final HashMap<AuditIo.ByteKey, Integer> localCidIndex = new HashMap<>();

    // ---------------------------------------------------------------- committed state

    private final AuditIo.Journal journal = new AuditIo.Journal();
    private final LevelState[] levels = {new LevelState(), new LevelState(), new LevelState()};
    private final TreeMap<Long, long[]> epochs = new TreeMap<>();
    private final TreeMap<Long, Stream> streams = new TreeMap<>();
    private final TreeSet<Long> retiredLocal = new TreeSet<>();
    private final TreeMap<Long, byte[][]> peerObserved = new TreeMap<>();
    private final HashMap<AuditIo.ByteKey, Long> peerOwner = new HashMap<>();
    private final TreeSet<Long> peerActive = new TreeSet<>();

    private int keysMask = 1;
    private long currentEpoch;
    private long used;
    private long sendMaxData;
    private long sendMaxStreamsBidi;
    private long sendMaxStreamsUni;
    private long openedBidi;
    private long openedUni;
    private long retirePriorTo;

    private boolean connectionClosed;
    private Object closedRow;

    // ---------------------------------------------------------------- entry point

    public Map<String, Object> audit(Main.Trace trace) {
        limitConnection = trace.connection;
        limitStream = trace.stream;
        limitBidi = trace.bidi;
        limitUni = trace.uni;
        cidLimit = trace.cidLimit;
        localBidi = trace.localBidi;
        localUni = trace.localUni;
        localCids = trace.localCids.toArray(new byte[0][]);
        cidWidth = localCids[0].length;
        for (int i = 0; i < localCids.length; i++) {
            localCidIndex.put(new AuditIo.ByteKey(localCids[i]), i);
        }
        byte[] peerCid = trace.peerCid;
        peerObserved.put(0L, new byte[][] {peerCid, trace.peerToken});
        peerOwner.put(new AuditIo.ByteKey(peerCid), 0L);
        peerActive.add(0L);
        for (int level = 0; level < 3; level++) {
            long seed = trace.received[level];
            if (seed >= 0) {
                levels[level].largest = seed;
                levels[level].seeded = true;
                levels[level].seen.add(seed);
                if (level == LEVEL_A) {
                    epochs.put(0L, new long[] {seed, seed, 1});
                }
            }
        }

        List<Object> packets = new ArrayList<>();
        List<Object> datagrams = new ArrayList<>();
        int event = 0;
        for (Main.Event item : trace.events) {
            if (item.keys != null) {
                if (!connectionClosed) {
                    int mask = 0;
                    for (String key : item.keys) {
                        mask |= key.equals("I") ? 1 : key.equals("H") ? 2 : 4;
                    }
                    keysMask = mask;
                }
            } else {
                processDatagram(event, item.wire, item.auth, packets, datagrams);
            }
            event++;
        }
        return report(packets, datagrams);
    }

    // ---------------------------------------------------------------- datagram walk

    private void processDatagram(
            int event, byte[] wire, List<Long> auth, List<Object> packets, List<Object> datagrams) {
        int position = 0;
        int reached = 0;
        int accepted = 0;
        long bytes = 0;
        MessageDigest datagramDigest = AuditIo.sha256();
        while (position < wire.length) {
            int headerOffset = position;
            Envelope envelope = parseHeader(wire, position);
            if (envelope == null) {
                packets.add(
                        Main.object(
                                "event",
                                event,
                                "packet",
                                reached,
                                "offset",
                                headerOffset,
                                "level",
                                null,
                                "pn",
                                null,
                                "epoch",
                                null,
                                "status",
                                BAD_HEADER,
                                "sha256",
                                null));
                reached++;
                break;
            }
            reached++;
            int packetIndex = reached - 1;
            LevelState level = levels[envelope.level];
            long expected = level.largest < 0 ? 0 : level.largest + 1;
            long pn = AuditIo.reconstruct(envelope.numberRaw, envelope.numberWidth, expected);
            Long annotation = null;
            Long epochOut = null;
            String shaOut = null;
            String status;
            journal.clear();
            try {
                if (connectionClosed) {
                    throw new Fail(CLOSED);
                }
                Integer destination = localCidIndex.get(new AuditIo.ByteKey(envelope.destination));
                if (destination == null || retiredLocal.contains((long) destination)) {
                    throw new Fail(DROP_CID);
                }
                if ((keysMask & (1 << envelope.level)) == 0) {
                    throw new Fail(NO_KEY);
                }
                if (pn > AuditIo.MAX62) {
                    throw new Fail(PN_RANGE);
                }
                Long claimed = envelopeIndex(auth, reached - 1);
                if (envelope.level == LEVEL_A) {
                    if (claimed == null
                            || !inWindow(claimed)
                            || (claimed & 1) != envelope.phase) {
                        throw new Fail(AUTH);
                    }
                } else {
                    if (claimed == null || claimed != 0) {
                        throw new Fail(AUTH);
                    }
                }
                annotation = claimed;
                epochOut = claimed;
                if (level.seen.contains(pn)) {
                    throw new Fail(DUPLICATE);
                }
                if (envelope.level == LEVEL_A && epochOrderingViolated(pn, claimed)) {
                    throw new Fail(KEY_UPDATE_ERROR);
                }
                ArrayList<Frame> frames = new ArrayList<>();
                long[] close = readFrames(wire, envelope, frames);
                byte[] canonicalPayload = canonicalize(frames);
                byte[] canonicalEnvelope =
                        canonicalEnvelope(envelope, pn, expected, canonicalPayload);
                shaOut = AuditIo.hex(AuditIo.sha256().digest(canonicalEnvelope));
                level.seen.add(pn);
                if (pn > level.largest) {
                    level.largest = pn;
                }
                if (envelope.level == LEVEL_A) {
                    recordEpoch(claimed, pn);
                }
                if (close == null) {
                    status = OK;
                } else {
                    closeConnection(close[0], close[1], event, packetIndex);
                    status = PEER_CLOSE;
                }
            } catch (Fail failure) {
                journal.undoAll();
                status = failure.status;
                if (KEY_UPDATE_ERROR.equals(status)) {
                    closeConnection(ERROR_KEY_UPDATE, 0, event, packetIndex);
                }
            }
            journal.commit();
            if (shaOut != null) {
                accepted++;
            }
            packets.add(
                    Main.object(
                            "event",
                            event,
                            "packet",
                            packetIndex,
                            "offset",
                            headerOffset,
                            "level",
                            LEVEL_NAMES[envelope.level],
                            "pn",
                            pn,
                            "epoch",
                            epochOut,
                            "status",
                            status,
                            "sha256",
                            shaOut));
            position = envelope.envelopeEnd;
        }
        datagrams.add(
                Main.object(
                        "event",
                        event,
                        "packets",
                        reached,
                        "accepted",
                        accepted,
                        "bytes",
                        bytes + datagramBytes.length,
                        "sha256",
                        AuditIo.hex(datagramDigest.digest())));
    }
}
